def standard():
    x = Symbol('x')
    h = expand((-24)*x**0+(27)*x**1+(-3)*x**2)
    pts = [Integer(1)] + sorted(set(r for r in solve(h, x) if r.is_real and 1 < r < 8)) + [Integer(8)]
    tot = 0
    for p_, q_ in zip(pts, pts[1:]):
        tot += Abs(integrate(h, (x, p_, q_)))
    tot = tot*Rational(2, 1)
    return int(tot)

def unique():
    return [standard()]
